### 5. Create API endpoints — `ShipmentTracker/ShipmentEndpoints.cs`

Create a static class with an extension method to map shipment API endpoints. These are needed because when running in WASM mode, the client can't access EF Core directly.

```csharp
using System.Security.Claims;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Data;

namespace ShipmentTracker;

public static class ShipmentEndpoints
{
    public static void MapShipmentApi(this WebApplication app)
    {
        var group = app.MapGroup("/api/shipments").RequireAuthorization();

        // GET all shipments (dispatchers see all, customers see only theirs)
        group.MapGet("/", async (ClaimsPrincipal user, ApplicationDbContext db, UserManager<ApplicationUser> userManager) =>
        {
            var email = user.FindFirstValue(ClaimTypes.Email) ?? user.FindFirstValue(ClaimTypes.Name) ?? "";
            var isDispatcher = user.IsInRole("Dispatcher");

            var query = isDispatcher
                ? db.Shipments.AsQueryable()
                : db.Shipments.Where(s => s.CustomerEmail == email);

            var shipments = await query.OrderByDescending(s => s.ShippedDate)
                .Select(s => new ShipmentDto
                {
                    Id = s.Id,
                    TrackingNumber = s.TrackingNumber,
                    Origin = s.Origin,
                    Destination = s.Destination,
                    Status = s.Status,
                    ShippedDate = s.ShippedDate,
                    EstimatedDelivery = s.EstimatedDelivery,
                    CustomerEmail = s.CustomerEmail,
                    Notes = s.Notes
                })
                .ToListAsync();

            return Results.Ok(shipments);
        });

        // GET single shipment by tracking number (public lookup — no auth required)
        app.MapGet("/api/shipments/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments
                .Where(s => s.TrackingNumber == trackingNumber)
                .Select(s => new ShipmentDto
                {
                    Id = s.Id,
                    TrackingNumber = s.TrackingNumber,
                    Origin = s.Origin,
                    Destination = s.Destination,
                    Status = s.Status,
                    ShippedDate = s.ShippedDate,
                    EstimatedDelivery = s.EstimatedDelivery,
                    CustomerEmail = s.CustomerEmail,
                    Notes = s.Notes
                })
                .FirstOrDefaultAsync();

            return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
        });

        // PUT update shipment status (dispatchers only)
        group.MapPut("/{id:int}", async (int id, ShipmentDto dto, ClaimsPrincipal user, ApplicationDbContext db) =>
        {
            if (!user.IsInRole("Dispatcher"))
                return Results.Forbid();

            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();

            shipment.Status = dto.Status;
            shipment.Notes = dto.Notes;
            shipment.EstimatedDelivery = dto.EstimatedDelivery;

            await db.SaveChangesAsync();
            return Results.Ok();
        });

        // POST create shipment (dispatchers only)
        group.MapPost("/", async (ShipmentDto dto, ClaimsPrincipal user, ApplicationDbContext db) =>
        {
            if (!user.IsInRole("Dispatcher"))
                return Results.Forbid();

            var shipment = new Shipment
            {
                TrackingNumber = dto.TrackingNumber,
                Origin = dto.Origin,
                Destination = dto.Destination,
                Status = dto.Status,
                ShippedDate = dto.ShippedDate,
                EstimatedDelivery = dto.EstimatedDelivery,
                CustomerEmail = dto.CustomerEmail,
                Notes = dto.Notes
            };

            db.Shipments.Add(shipment);
            await db.SaveChangesAsync();
            return Results.Created($"/api/shipments/{shipment.Id}", new ShipmentDto
            {
                Id = shipment.Id,
                TrackingNumber = shipment.TrackingNumber,
                Origin = shipment.Origin,
                Destination = shipment.Destination,
                Status = shipment.Status,
                ShippedDate = shipment.ShippedDate,
                EstimatedDelivery = shipment.EstimatedDelivery,
                CustomerEmail = shipment.CustomerEmail,
                Notes = shipment.Notes
            });
        });
    }
}
```

