using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class ShipmentService
{
    private readonly HttpClient _http;

    public ShipmentService(HttpClient http)
    {
        _http = http;
    }

    public async Task<List<ShipmentDto>> GetShipmentsAsync()
    {
        var result = await _http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments");
        return result ?? [];
    }

    public async Task<ShipmentDto?> TrackShipmentAsync(string trackingNumber)
    {
        var response = await _http.GetAsync($"/api/shipments/track/{trackingNumber}");
        if (response.IsSuccessStatusCode)
            return await response.Content.ReadFromJsonAsync<ShipmentDto>();
        return null;
    }

    public async Task UpdateShipmentAsync(ShipmentDto shipment)
    {
        await _http.PutAsJsonAsync($"/api/shipments/{shipment.Id}", shipment);
    }

    public async Task<ShipmentDto?> CreateShipmentAsync(ShipmentDto shipment)
    {
        var response = await _http.PostAsJsonAsync("/api/shipments", shipment);
        if (response.IsSuccessStatusCode)
            return await response.Content.ReadFromJsonAsync<ShipmentDto>();
        return null;
    }
}

