@code {
    private List<ShipmentDto>? shipments;
    private string filterText = "";
    private ShipmentDto? editingShipment;
    private ShipmentDto formModel = new() { ShippedDate = DateTime.UtcNow, EstimatedDelivery = DateTime.UtcNow.AddDays(7), Status = "Pending" };
    private string? statusMessage;

    private IEnumerable<ShipmentDto> FilteredShipments =>
        shipments?.Where(s =>
            string.IsNullOrEmpty(filterText) ||
            s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.Status.Contains(filterText, StringComparison.OrdinalIgnoreCase)) ?? [];

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentSvc.GetShipmentsAsync();
    }

    private void StartEdit(ShipmentDto s)
    {
        editingShipment = s;
        formModel = new ShipmentDto
        {
            Id = s.Id,
            TrackingNumber = s.TrackingNumber,
            Origin = s.Origin,
            Destination = s.Destination,
            Status = s.Status,
            ShippedDate = s.ShippedDate,
            EstimatedDelivery = s.EstimatedDelivery,
            CustomerEmail = s.CustomerEmail,
            Notes = s.Notes
        };
        statusMessage = null;
    }

    private async Task SaveEdit()
    {
        await ShipmentSvc.UpdateShipmentAsync(formModel);
        statusMessage = "Shipment updated!";
        shipments = await ShipmentSvc.GetShipmentsAsync();
        editingShipment = null;
        ResetForm();
    }

    private void CancelEdit()
    {
        editingShipment = null;
        ResetForm();
        statusMessage = null;
    }

    private async Task CreateShipment()
    {
        var created = await ShipmentSvc.CreateShipmentAsync(formModel);
        if (created is not null)
        {
            statusMessage = $"Shipment {created.TrackingNumber} created!";
            shipments = await ShipmentSvc.GetShipmentsAsync();
            ResetForm();
        }
    }

    private void ResetForm()
    {
        formModel = new ShipmentDto { ShippedDate = DateTime.UtcNow, EstimatedDelivery = DateTime.UtcNow.AddDays(7), Status = "Pending" };
    }

    private static string GetStatusBadge(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "In Transit" => "bg-primary",
        "Customs Clearance" => "bg-warning text-dark",
        "Out for Delivery" => "bg-info text-dark",
        "Delivered" => "bg-success",
        "Returned" => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@rendermode InteractiveAuto
@inject ShipmentService ShipmentSvc

<PageTitle>Track Shipment</PageTitle>

<h1>Track Your Shipment</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g. TRK-20260001)"
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="Search" disabled="@isSearching">
                @(isSearching ? "Searching..." : "Track")
            </button>
        </div>
    </div>
</div>

@if (searchPerformed && shipment is null)
{
    <div class="alert alert-warning">
        No shipment found with tracking number <strong>@searchedNumber</strong>. Please check the number and try again.
    </div>
}

@if (shipment is not null)
{
    <div class="card">
        <div class="card-header d-flex justify-content-between align-items-center">
            <h4 class="mb-0">Shipment @shipment.TrackingNumber</h4>
            <span class="badge @GetStatusBadge(shipment.Status) fs-6">@shipment.Status</span>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <h5>Route</h5>
                    <p class="mb-1"><strong>Origin:</strong> @shipment.Origin</p>
                    <p><strong>Destination:</strong> @shipment.Destination</p>
                </div>
                <div class="col-md-6">
                    <h5>Dates</h5>
                    <p class="mb-1"><strong>Shipped:</strong> @shipment.ShippedDate.ToString("MMMM dd, yyyy")</p>
                    <p><strong>Estimated Delivery:</strong> @shipment.EstimatedDelivery.ToString("MMMM dd, yyyy")</p>
                </div>
            </div>

            @if (shipment.Status != "Delivered")
            {
                <div class="mt-3">
                    <h5>Delivery Countdown</h5>
                    @{
                        var daysLeft = (shipment.EstimatedDelivery - DateTime.UtcNow).Days;
                    }
                    @if (daysLeft > 0)
                    {
                        <div class="progress" style="height: 25px;">
                            @{
                                var totalDays = (shipment.EstimatedDelivery - shipment.ShippedDate).Days;
                                var elapsed = (DateTime.UtcNow - shipment.ShippedDate).Days;
                                var pct = totalDays > 0 ? Math.Min(100, (int)(elapsed * 100.0 / totalDays)) : 0;
                            }
                            <div class="progress-bar bg-primary" style="width: @(pct)%">
                                @pct% — @daysLeft day(s) remaining
                            </div>
                        </div>
                    }
                    else
                    {
                        <div class="alert alert-danger">
                            Delivery is overdue by @Math.Abs(daysLeft) day(s).
                        </div>
                    }
                </div>
            }
            else
            {
                <div class="alert alert-success mt-3">
                    <strong>Delivered!</strong> This shipment was delivered.
                </div>
            }

            @if (!string.IsNullOrEmpty(shipment.Notes))
            {
                <div class="mt-3">
                    <h5>Notes</h5>
                    <p>@shipment.Notes</p>
                </div>
            }
        </div>
    </div>
}

@code {
    private string trackingNumber = "";
    private string searchedNumber = "";
    private ShipmentDto? shipment;
    private bool searchPerformed;
    private bool isSearching;

    private async Task Search()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        isSearching = true;
        searchedNumber = trackingNumber.Trim();
        shipment = await ShipmentSvc.TrackShipmentAsync(searchedNumber);
        searchPerformed = true;
        isSearching = false;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await Search();
    }

    private static string GetStatusBadge(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "In Transit" => "bg-primary",
        "Customs Clearance" => "bg-warning text-dark",
        "Out for Delivery" => "bg-info text-dark",
        "Delivered" => "bg-success",
        "Returned" => "bg-danger",
        _ => "bg-secondary"
    };
}

